import { internet, name } from "faker/locale/en_US";

import type { RAFile, Sale } from "../../../types";
import type { Db } from "./types";

export const generateSales = (_: Db): Sale[] => {
  const randomSales = Array.from(Array(5).keys()).map((id) => {
    const first_name = name.firstName();
    const last_name = name.lastName();
    const email = internet.email(first_name, last_name);

    return {
      id: id + 1,
      user_id: `${id + 1}`,
      first_name,
      last_name,
      email,
      secondary_emails: [],
      password: "demo",
      administrator: false,
      disabled: false,
    };
  });
  return [
    {
      id: 0,
      user_id: "0",
      first_name: "Jane",
      last_name: "Doe",
      email: "janedoe@atomic.dev",
      secondary_emails: [],
      password: "demo",
      administrator: true,
      disabled: false,
      avatar: {
        src: "data:image/jpeg;base64,",
      } as RAFile,
    },
    ...randomSales,
  ];
};
